// @pit: {"label": "Remove pi-action-context extension and route project_context through builtin"}
async ({ workspace: { read, edit } }) => {
  const rep = async (file: string, pairs: [string, string][]) => {
    const r = await read(file, { format: "raw" });
    let c = r.content;
    for (const [a, b] of pairs) {
      if (!c.includes(a)) throw new Error(`${file}: missing ${a.slice(0, 60)}`);
      c = c.replace(a, b);
    }
    await edit(file, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  };
  await rep("src/context-files.ts", [
    [`import {
	defineExtension,
	type Extension,
	section,
} from "@earendil-works/pi-durable";

`, ``],
    [`/** The built-in pi-durable extension with the \`project_context\` section; installed right after the coding tools. */
export const CONTEXT_EXTENSION = "pi-action-context";
export const PROJECT_CONTEXT_SECTION`, `/** The key of the section with the context files, in the built-in \`pi-action\` extension (builtin-extension.ts). */
export const PROJECT_CONTEXT_SECTION`],
    [`
/**
 * The \`pi-action-context\` extension: the \`project_context\` section with \`text\`, read once for the run, so that the
 * agent's edits of AGENTS.md during the run don't change the prompt (and its cache). No section when \`text\` is
 * undefined.
 */
export function contextExtension(text: string | undefined): Extension {
	return defineExtension({
		name: CONTEXT_EXTENSION,
		sections: [section(PROJECT_CONTEXT_SECTION, () => text)],
	});
}
`, ``],
  ]);
  await rep("src/thread.ts", [
    [`import { contextExtension } from "./context-files.ts";
`, ``],
    [`	/** The \`project_context\` section (see context-files.ts), read once for the run; none when undefined. */
	projectContext?: string | undefined;
	/** pi-durable extensions from the \`extensions\` input, installed after the coding tools and pi-action-context. */`,
     `	/** pi-durable extensions, installed after the coding tools: the built-in \`pi-action\`, then the \`extensions\` input's. */`],
    [`		// Before the extensions' sections: the repository's rules come first, then pit's guidelines.
		registry.install(contextExtension(options.projectContext));
`, ``],
  ]);
  await rep("src/durable-extensions.ts", [
    [`import { CONTEXT_EXTENSION } from "./context-files.ts";
`, ``],
    [`with its built-in extensions (pi-action-context, pi-action)`, `with its built-in extension (pi-action)`],
    [`	const names = new Set([
		CodingTools.name,
		CONTEXT_EXTENSION,
		BUILTIN_EXTENSION,
	]);`, `	const names = new Set([CodingTools.name, BUILTIN_EXTENSION]);`],
  ]);
  await rep("src/run.ts", [
    [`			projectContext: context,
			extensions: [createBuiltinExtension({ skills }), ...extensions],`,
     `			extensions: [
				createBuiltinExtension({ projectContext: context, skills }),
				...extensions,
			],`],
  ]);
  return "ok";
}
